import java.util.*;

class Solution {
    public int countReachable(int n, int[][] edges, int start) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        boolean[] seen = new boolean[n];
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(start);
        seen[start] = true;
        int count = 0;
        while (!stack.isEmpty()) {
            int node = stack.pop();
            count++;
            for (int next : adj.get(node)) {
                if (!seen[next]) {
                    seen[next] = true;
                    stack.push(next);
                }
            }
        }
        return count;
    }
}

